let lang=new URLSearchParams(location.search).get('lang')==='id'?'id':'en';
let route=location.pathname.split('/').filter(Boolean)[0]||'home';if(!pages[route])route='home';
const t=(id,en)=>lang==='id'?id:en, v=o=>o[lang], href=r=>'/'+(r==='home'?'':r+'/')+'?lang='+lang;
const link=(r,text,cls='')=>`<a class="${cls}" href="${href(r)}">${text}</a>`;
function featureRows(p){return p.features?`<section class="wrap features"><p class="eyebrow">${t('KAPABILITAS','CAPABILITIES')}</p>${p.features.map((f,i)=>`<div class="feature"><span class="num">0${i+1}</span><h3>${f[lang==='id'?0:1]}</h3><p>${f[lang==='id'?2:3]}</p></div>`).join('')}</section>`:''}
function benefits(p){if(!p.benefits)return '';const isApplications=['about','energy'].includes(route);const titles=v(p.benefits);const details=benefitDetails[route];return `<section class="benefits wrap"><p class="eyebrow">${isApplications?t('BIDANG PENERAPAN','APPLICATION AREAS'):t('MANFAAT & KEUNGGULAN','BENEFITS & ADVANTAGES')}</p>${details?`<div class="benefit-grid">${titles.map((title,i)=>`<article class="benefit-item"><img class="benefit-icon" src="/assets/icons/${details[i][0]}.svg" alt="" width="42" height="42" loading="lazy"><h3>${title}</h3><p>${details[i][lang==='id'?1:2]}</p></article>`).join('')}</div>`:`<div class="tags">${titles.map(x=>`<span>${x}</span>`).join('')}</div>`}${p.extra?`<p class="lead">${v(p.extra)}</p>`:''}</section>`}
function sectorList(){return `<div class="sector-list sector-gallery">${sectors.map((s,i)=>link(s[0],`<div class="sector-photo"><img src="/assets/${sectionImages[s[0]]}" alt="${s[lang==='id'?1:2]}" loading="lazy" decoding="async"></div><div class="sector-copy"><span class="num">0${i+1}</span><div><h3>${s[lang==='id'?1:2]}</h3><p>${s[lang==='id'?3:4]}</p></div><span class="textlink">${t('Jelajahi','Explore')}</span></div>`)).join('')}</div>`}
function serviceList(){return `<div class="service-grid service-gallery">${services.map((s,i)=>link(s[0],`<div class="service-photo"><img src="/assets/${sectionImages[s[0]]}" alt="${s[lang==='id'?1:2]}" loading="lazy" decoding="async"></div><span class="num">0${i+1}</span><h3>${s[lang==='id'?1:2]}</h3><p>${s[lang==='id'?3:4]}</p><span class="textlink">${t('Lihat layanan','View service')}</span>`)).join('')}</div>`}
function softwareGrid(full=false){return `<div class="software-grid">${software.map((s,i)=>`<article><a href="${full?'#software-'+i:href('software')+'#software-'+i}"><div class="product-image"><img src="/assets/${s.image}" alt="${s.name}" loading="lazy"></div><div class="product-head"><span class="num">0${i+1}</span><h3>${s.name}</h3></div><p>${s[lang]}</p></a>${full?`<ul id="software-${i}" class="product-links">${s.links.map(l=>`<li><a href="${l.url}" target="_blank" rel="noopener noreferrer">${lang==='id'?(productTranslations[l.name]||l.name):l.name}</a></li>`).join('')}</ul>`:''}</article>`).join('')}</div>`}
function trainingDetails(){const focus=[['sliders-horizontal','Pengembangan kurikulum sesuai kebutuhan','Customized curriculum development'],['graduation-cap','Pelatihan engineering khusus','Specialized engineering training'],['gauge','Perbaikan dan optimasi proses','Process improvement and optimization'],['factory','Pelatihan spesifik industri','Industry-specific training']];return `<section class="wrap training-scope"><p class="eyebrow">${t('CAKUPAN CUSTOM TRAINING','CUSTOM TRAINING SCOPE')}</p><h2>${t('Pelatihan sesuai<br><em>kebutuhan tim Anda.</em>','Training shaped around<br><em>your team’s needs.</em>')}</h2><div class="training-focus">${focus.map(f=>`<article><img class="benefit-icon" src="/assets/icons/${f[0]}.svg" alt="" width="42" height="42" loading="lazy"><h3>${f[lang==='id'?1:2]}</h3></article>`).join('')}</div></section><section class="wrap training-delivery"><p class="eyebrow">${t('METODE PELAKSANAAN','TRAINING DELIVERY')}</p><h2>${t('Tatap muka.<br><em>Atau secara online.</em>','In class.<br><em>Or online.</em>')}</h2><div class="training-methods"><article><img class="benefit-icon" src="/assets/icons/users.svg" alt="" width="42" height="42" loading="lazy"><h3>${t('Pelatihan tatap muka','In-class training')}</h3><p>${t('Sesi workshop dengan praktik langsung.','Hands-on workshop sessions.')}</p><dl><dt>Off-site</dt><dd>${t('Dilaksanakan di fasilitas Parametrik.','Conducted at our facility.')}</dd><dt>On-site</dt><dd>${t('Dilaksanakan di fasilitas pelanggan.','Conducted at the client’s facility.')}</dd></dl></article><article><img class="benefit-icon" src="/assets/icons/monitor-smartphone.svg" alt="" width="42" height="42" loading="lazy"><h3>${t('Pelatihan online','Online training')}</h3><dl><dt>${t('Kelas virtual interaktif','Interactive virtual classes')}</dt><dd>${t('Pembelajaran langsung bersama instruktur secara online.','Live online learning with instructors.')}</dd><dt>${t('E-learning mandiri','Self-paced e-learning')}</dt><dd>${t('Modul pembelajaran fleksibel yang dapat diikuti sesuai kecepatan peserta.','Flexible learning modules participants can complete at their own pace.')}</dd></dl></article></div></section>`}
function home(){return `<section class="visual"><img src="/assets/hero.jpg" alt="${t('Desain dan pengembangan produk','Product design and development')}"><div class="visual-caption"><span class="eyebrow">ENGINEERING · SOFTWARE · IOT</span><h2>${t('Teknologi bertemu<br>kebutuhan nyata.','Technology meets<br>real-world needs.')}</h2></div></section><section class="wrap section"><div class="section-top"><span class="eyebrow">01 / SOFTWARE</span>${link('software',t('Semua solusi software','All software solutions'),'textlink')}</div><div class="split-title"><h2>${t('Perangkat yang tepat.<br><em>Di setiap tahap desain.</em>','The right tools.<br><em>At every design stage.</em>')}</h2><p>${t('Dari pemodelan dan simulasi hingga pengelolaan siklus hidup produk.','From modeling and simulation to product lifecycle management.')}</p></div>${softwareGrid()}</section><section class="dark section"><div class="wrap"><div class="section-top"><span class="eyebrow">02 / INTERNET OF THINGS</span>${link('iot',t('Kenali solusi IoT','Discover IoT solutions'),'textlink')}</div><h2>${t('Terhubung.<br><em>Terpantau. Terintegrasi.</em>','Connected.<br><em>Monitored. Integrated.</em>')}</h2>${sectorList()}</div></section><section class="wrap section"><span class="eyebrow">03 / ${t('LAYANAN','SERVICES')}</span><h2>${t('Keahlian untuk<br><em>melangkah lebih jauh.</em>','Expertise to<br><em>move forward.</em>')}</h2>${serviceList()}</section><section class="wrap section articles"><span class="eyebrow">04 / ${t('ARTIKEL & WAWASAN','ARTICLES & INSIGHTS')}</span><h2>${t('Pengetahuan yang<br><em>terus berkembang.</em>','Knowledge that<br><em>keeps growing.</em>')}</h2><div class="article-grid"><a href="https://www.parametris.com/mathcad-software-in-jakarta/" target="_blank" rel="noopener noreferrer"><span class="eyebrow">SOFTWARE</span><h3>${t('Software Mathcad di Jakarta','Mathcad Software in Jakarta')}</h3><span class="textlink">${t('Baca artikel asli','Read original article')}</span></a><a href="https://www.parametris.com/parametrik-training-certification/" target="_blank" rel="noopener noreferrer"><span class="eyebrow">${t('PELATIHAN','TRAINING')}</span><h3>${t('Pelatihan & sertifikasi Parametrik: tingkatkan keterampilan bersama reseller PTC di Jakarta','Parametrik Training & Certification: Boost Skills with PTC Reseller in Jakarta')}</h3><span class="textlink">${t('Baca artikel asli','Read original article')}</span></a></div></section>`}
function contact(){return `<section class="wrap contact-layout"><div><p class="eyebrow">${t('HUBUNGI TIM KAMI','GET IN TOUCH')}</p><a class="contact-big" href="mailto:sales@parametris.com">sales@parametris.com</a><p>${t('Dukungan teknis','Technical support')}: <a href="mailto:support@parametris.com">support@parametris.com</a></p><div class="contact-actions"><a class="button filled" href="https://api.whatsapp.com/send?phone=6282116291814" target="_blank" rel="noopener noreferrer">WhatsApp</a><a class="button" href="tel:+622130448230">+62 21 3044 8230</a></div><p>WhatsApp: +62 821 1629 1814<br>Fax: +62 21 3044 8240</p></div><div class="address"><p class="eyebrow">${t('ALAMAT','ADDRESS')}</p><h3>Synergy Building<br>Suite 1508</h3><p>Jalur Sutera Barat Kav. 17<br>Alam Sutera<br>Tangerang 15325 – Indonesia</p></div></section>`}
function render(){const p=pages[route];document.documentElement.lang=lang;document.title=`${route==='home'?'Parametrik — Software, IoT & Engineering':v(p.label).split(' / ').pop()+' — Parametrik'}`;document.querySelector('meta[name=description]').content=v(p.intro);document.getElementById('app').innerHTML=`<a class="skip" href="#main">${t('Langsung ke konten','Skip to content')}</a><header><div class="header-inner"><a href="${href('home')}" aria-label="Parametrik"><img class="logo" src="/assets/logo.png" alt="Parametrik"></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">${t('Menu','Menu')}</button><nav id="navigation" aria-label="${t('Navigasi utama','Main navigation')}">${link('home',t('Beranda','Home'),route==='home'?'active':'')}<details class="nav-dropdown"><summary>${t('Produk','Products')}</summary><div>${link('software','Software')}${link('iot','Internet of Things')}</div></details><details class="nav-dropdown"><summary>${link('services',t('Layanan','Services'))}</summary><div>${services.map(s=>link(s[0],s[lang==='id'?1:2])).join('')}</div></details>${link('about',t('Tentang kami','About us'))}${link('contact',t('Mari berdiskusi','Let’s talk'),'nav-cta')}</nav><div class="languages" aria-label="${t('Bahasa','Language')}"><button data-lang="en" aria-pressed="${lang==='en'}">EN</button><button data-lang="id" aria-pressed="${lang==='id'}">ID</button></div></div></header><main id="main"><section class="hero wrap ${route==='home'?'':'inner-hero'} ${route==='services'?'services-hero':''}"><div class="hero-label"><span class="eyebrow">${route==='home'?'PT PARAMETRIK SOLUSI INTEGRASI':v(p.label)}</span><span class="eyebrow">${route==='home'?t('DARI KONSEP MENUJU REALISASI','FROM CONCEPT TO REALITY'):link('home',t('Beranda','Home'))}</span></div><h1>${v(p.title)}</h1><div class="hero-bottom"><p>${v(p.intro)}</p>${route==='home'?link('software',t('Jelajahi produk','Explore products'),'button'):route==='contact'?'':link('contact',t('Diskusikan kebutuhan','Discuss your needs'),'button')}</div></section>${route==='home'?home():route==='contact'?contact():`${p.image?`<figure class="detail-image wrap"><img src="/assets/${p.image}" alt="${v(p.label)}" decoding="async"></figure>`:''}${route==='software'?`<section class="wrap section">${softwareGrid(true)}</section>`:''}${['iot'].includes(route)?`<section class="dark section"><div class="wrap">${sectorList()}</div></section>`:''}${route==='services'?`<section class="wrap section">${serviceList()}</section>`:''}${featureRows(p)}${route==='training'?trainingDetails():''}${benefits(p)}`}${route!=='contact'?`<section class="closing"><div class="wrap"><span class="eyebrow">${t('MULAI PERCAKAPAN','START A CONVERSATION')}</span><h2>${t('Kebutuhan Anda.<br><em>Langkah kita berikutnya.</em>','Your needs.<br><em>Our next step.</em>')}</h2>${link('contact',t('Diskusikan kebutuhan Anda','Let’s discuss your needs'),'button')}</div></section>`:''}</main><footer class="wrap"><div class="footer-grid"><div><img class="logo" src="/assets/logo.png" alt="Parametrik"><p>PT Parametrik Solusi Integrasi</p><p>${t('Produk dan layanan untuk engineering,<br>manufaktur, dan teknologi terhubung.','Products and services for engineering,<br>manufacturing, and connected technology.')}</p></div><div><span class="eyebrow">${t('JELAJAHI','EXPLORE')}</span>${link('software','Software')}${link('iot','Internet of Things')}${link('services',t('Layanan','Services'))}${link('about',t('Tentang kami','About us'))}</div><div><span class="eyebrow">${t('HUBUNGI KAMI','CONTACT US')}</span><a href="mailto:support@parametris.com">support@parametris.com</a><a href="tel:+622130448230">+62 21 3044 8230</a>${link('contact','Alam Sutera · Tangerang')}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} PT Parametrik Solusi Integrasi</span><div><a href="https://www.instagram.com/parametriksi/" target="_blank" rel="noopener noreferrer">Instagram</a><a href="https://www.linkedin.com/company/parametrik-solusi-integrasi/" target="_blank" rel="noopener noreferrer">LinkedIn</a><a href="https://www.youtube.com/@parametriksi" target="_blank" rel="noopener noreferrer">YouTube</a></div></div></footer>`;
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{let y=window.scrollY;lang=b.dataset.lang;history.replaceState({},'',href(route)+location.hash);render();window.scrollTo(0,y)}));document.querySelector('.menu-toggle').addEventListener('click',e=>{let open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',open);document.querySelector('nav').classList.toggle('open',open)});document.querySelectorAll('.nav-dropdown').forEach(d=>{
const closeOthers=()=>document.querySelectorAll('.nav-dropdown').forEach(o=>{if(o!==d)o.open=false});
d.addEventListener('toggle',()=>{if(d.open)closeOthers()});
d.addEventListener('focusin',()=>{closeOthers();d.open=true});
d.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&window.matchMedia('(min-width: 781px)').matches){closeOthers();d.open=true}});
d.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'&&window.matchMedia('(min-width: 781px)').matches)d.open=false});
d.addEventListener('focusout',e=>{if(!d.contains(e.relatedTarget))d.open=false});
});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('details').forEach(d=>d.open=false)},{once:true});}
render();
